import React, { useState } from 'react';
import './Navbar.css';
import { Link } from 'react-router-dom';

const Navbar = () => {
  const [menu, setMenu] = useState("Home");

  return (
    <div className='navbar'>
      <div className='nav-logo'>
        <img src={logo} alt="HEXCART Logo" style={{ width: '50px', height: 'auto' }} />
        <p id="n1">HEX</p>
        <p id="n2">CART</p>
      </div>

      <ul className='nav-menu'>
        <li onClick={() => setMenu("Home")}>
          <Link style={{ textDecoration: 'none' }} to='/'>Home</Link>
          {menu === "Home" ? <hr /> : null}
        </li>
        <li onClick={() => setMenu("Products")}>
          <Link style={{ textDecoration: 'none' }} to='/Products'>Products</Link>
          {menu === "Products" ? <hr /> : null}
        </li>
        <li onClick={() => setMenu("About")}>
          <Link style={{ textDecoration: 'none' }} to='/About'>About</Link>
          {menu === "About" ? <hr /> : null}
        </li>
        <li onClick={() => setMenu("NewArrivals")}>
          <Link style={{ textDecoration: 'none' }} to='/NewArrivals'>NewArrivals</Link>
          {menu === "NewArrivals" ? <hr /> : null}
        </li>
        <li onClick={() => setMenu("Contact")}>
          <Link style={{ textDecoration: 'none' }} to='/Contact'>Contact</Link>
          {menu === "Contact" ? <hr /> : null}
        </li>
        <li onClick={() => setMenu("Cart")}>
          <Link style={{ textDecoration: 'none' }} to='/Cart'>Cart</Link>
          {menu === "Cart" ? <hr /> : null}
        </li>
      </ul>

      <div className="nav-login-cart">
        <input type="text" placeholder='Search' />
        <Link style={{ textDecoration: 'none' }} to='/login?mode=login'>
          <button onClick={() => setMenu("")}>Login</button>
        </Link>
        <Link style={{ textDecoration: 'none' }} to='/login?mode=signup'>
          <button onClick={() => setMenu("")}>Signup</button>
        </Link>
      </div>
    </div>
  );
};

export default Navbar;
